'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette=['#287c82','#a26b36','#5375a1','#8b699a','#71925c','#b76a5e','#408a61','#9a6b58','#6477a2'];
let data, map, visible=[], selected=null, showLabels=false, date=null;
const markers=new Map(),colors=new Map();
const hiddenPlaces=new Set(), STORAGE_KEY='chuanxi-map-state-v1';
let ready=false;
function saveState(){if(!ready)return;try{const center=map.getCenter();localStorage.setItem(STORAGE_KEY,JSON.stringify({hidden:[...hiddenPlaces],showLabels,date,selected:selected?.id,query:$('search').value,region:$('region').value,altitude:$('altitude').value,walking:$('walking').checked,center:[center.lat,center.lng],zoom:map.getZoom(),listScroll:$('place-list').scrollTop}));$('save-status').textContent='操作已自动保存到此浏览器';}catch{$('save-status').textContent='浏览器未允许保存；刷新后操作可能丢失';}}
function readState(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||{};}catch{return {};}}
function mapPlaces(){return visible.filter(r=>!hiddenPlaces.has(r.id));}
function locateInList(id){const list=$('place-list'),row=list.querySelector(`[data-row="${id}"]`);if(!row)return;const a=list.getBoundingClientRect(),b=row.getBoundingClientRect();list.scrollTop+=b.top-a.top-(a.height-b.height)/2;}
function togglePlace(id){if(hiddenPlaces.has(id))hiddenPlaces.delete(id);else hiddenPlaces.add(id);if(selected?.id===id&&hiddenPlaces.has(id))closeDetail();renderList();renderMarkers();$('place-list').querySelector(`[data-toggle="${id}"]`)?.focus({preventScroll:true});saveState();}

const longWalk=new Set(['P07','P21','P22','P38','P39','P41']);
function pretty(r){return r.display_name||r.name;}
const elevationBands=[{max:2500,color:'#27845c',label:'低于 2,500 m'},{max:3500,color:'#3679bd',label:'2,500–3,499 m'},{max:4500,color:'#ce7b23',label:'3,500–4,499 m'},{max:Infinity,color:'#c63e3e',label:'4,500 m 及以上'}];
function altitudeColor(r){return Number.isFinite(r.elevation)?elevationBands.find(b=>r.elevation<b.max).color:'#788388';}
function renderElevationLegend(){$('legend').innerHTML='<strong>海拔</strong>'+[...elevationBands,{color:'#788388',label:'暂无海拔'}].map(b=>`<span style="--point-color:${b.color}"><i></i>${b.label}</span>`).join('');}
const DAY_KEY='chuanxi-place-days-v1';
let placeDays={};
try{const saved=JSON.parse(localStorage.getItem(DAY_KEY));if(saved&&typeof saved==='object'&&!Array.isArray(saved))placeDays=saved;}catch{}
function dayKey(r){return `${r.id}:${r.lat}:${r.lon}`;}
function placeDay(r){const n=placeDays[dayKey(r)];return Number.isInteger(n)&&n>=1&&n<=99?n:null;}
function plannedDate(r){const n=placeDay(r);return n===null?null:TripDates.addDays(data.trip_dates[0],n-1);}
function dayMessage(r){const d=plannedDate(r);return d?`第 ${placeDay(r)} 天 · ${d}${data.trip_dates.includes(d)?'；已定位对应天气日期。':'；超出当前行程，请调整天数或出行日期。'}`:'填写 1 表示第 1 天；同一天可安排多个地点。';}
function initDayEditor(r){$('day-form').onsubmit=e=>{e.preventDefault();const raw=$('place-day').value.trim(),n=raw===''?null:Number(raw);if(n!==null&&(!Number.isInteger(n)||n<1||n>99)){$('day-message').textContent='请输入 1 至 99 的整数，或留空取消。';return;}const next={...placeDays};if(n===null)delete next[dayKey(r)];else next[dayKey(r)]=n;try{localStorage.setItem(DAY_KEY,JSON.stringify(next));}catch{$('day-message').textContent='保存失败，请检查浏览器存储设置后重试。';return;}placeDays=next;renderMarkers();renderDetail();saveState();if(n===null)$('day-message').textContent='已取消天数标记';};$('clear-day').onclick=()=>{$('place-day').value='';$('day-form').requestSubmit();};}
function icon(r,active=false){const style={className:'map-pin'+(active?' selected':''),html:`<div class="pin-inner" style="--point-color:${altitudeColor(r)}">${placeDay(r)===null?'<span class="pin-dot" aria-hidden="true"></span>':`<span class="pin-day" aria-hidden="true">${placeDay(r)}</span>`}</div>`,iconSize:[32,36],iconAnchor:[16,33]};return map?.provider==='amap'?style:L.divIcon(style);}
function link(r){return `https://uri.amap.com/marker?position=${r.lon},${r.lat}&name=${encodeURIComponent(pretty(r))}&coordinate=wgs84&callnative=1`;}
function filter(){const query=$('search').value.trim().toLocaleLowerCase(),g=$('region').value,a=$('altitude').value;visible=data.records.filter(r=>(!query||[r.name,r.display_name,r.group,r.original_name].join(' ').toLocaleLowerCase().includes(query))&&(!g||r.group===g)&&(!a||(Number.isFinite(r.elevation)&&(a==='high'?r.elevation>=4000:r.elevation<Number(a))))&&(!$('walking').checked||!longWalk.has(r.id)));renderList();renderMarkers();if(selected&&!visible.some(r=>r.id===selected.id))closeDetail();if(visible.length)fit();saveState();}
function renderList(){const list=$('place-list'),top=list.scrollTop;$('count').textContent=`${visible.length} / ${data.records.length} · 地图 ${mapPlaces().length}`;list.innerHTML=visible.length?visible.map(r=>`<div class="place-row ${hiddenPlaces.has(r.id)?'is-hidden':''}" data-row="${r.id}" role="listitem"><button type="button" class="place-card ${selected?.id===r.id?'active':''}" data-id="${r.id}" aria-pressed="${selected?.id===r.id}" style="--point-color:${altitudeColor(r)}"><span class="place-number" aria-hidden="true"></span><span class="place-copy"><span class="place-name">${esc(pretty(r))}</span><span class="place-meta">${esc(r.group)} · ${Number.isFinite(r.elevation)?r.elevation.toLocaleString()+' m':'海拔暂无'}${hiddenPlaces.has(r.id)?' · 地图已隐藏':''}</span></span></button><button type="button" class="visibility-toggle" data-toggle="${r.id}" aria-label="${hiddenPlaces.has(r.id)?'显示':'隐藏'}${esc(pretty(r))}" aria-controls="map">${hiddenPlaces.has(r.id)?'显示':'隐藏'}</button></div>`).join(''):'<p class="empty">没有符合条件的地点<br>试试更换区域或放宽海拔范围。</p>';list.scrollTop=top;}
function renderMarkers(){markers.forEach(m=>map.removeLayer(m));markers.clear();mapPlaces().forEach(r=>{const marker=map.marker(r,icon(r,selected?.id===r.id));const labelMarker=()=>marker.getElement()?.setAttribute('aria-label',pretty(r));marker.on('add',labelMarker);labelMarker();marker.on('click',()=>select(r.id,{fromMap:true}));markers.set(r.id,marker);});updateLabels();}
function updateLabels(){map.labels(mapPlaces().filter(r=>showLabels||selected?.id===r.id));$('labels-toggle').setAttribute('aria-pressed',String(showLabels));$('labels-toggle').textContent=showLabels?'隐藏地名':'显示地名';}
function fit(){const points=mapPlaces();if(points.length)map.fit(points);}
function select(id,{fromMap=false}={}){const r=data.records.find(x=>x.id===id);if(!r)return;const prev=selected;selected=r;if(prev&&markers.has(prev.id))markers.get(prev.id).setIcon(icon(prev));if(markers.has(r.id))markers.get(r.id).setIcon(icon(r,true));$('detail').hidden=false;renderDetail();renderList();document.querySelector('.sidebar').classList.remove('open');$('list-toggle').setAttribute('aria-expanded','false');$('list-toggle').textContent='地点列表';const zoom=Math.max(map.getZoom(),9);map.setView([r.lat,r.lon],zoom,{animate:false});if(innerWidth>720)map.panBy([160,0],{animate:false});else map.panBy([0,140],{animate:false});updateLabels();if(fromMap&&innerWidth<=720){document.querySelector('.sidebar').classList.add('open');$('list-toggle').setAttribute('aria-expanded','true');$('list-toggle').textContent='关闭列表';}locateInList(id);saveState();}
function closeDetail(){if(selected&&markers.has(selected.id))markers.get(selected.id).setIcon(icon(selected));selected=null;$('detail').hidden=true;renderList();updateLabels();saveState();}
function value(arr,i,suffix=''){return i>=0&&arr?.[i]!=null?`${arr[i]}${suffix}`:'—';}
function range(f,i){if(i<0||f.temperature_2m_min?.[i]==null||f.temperature_2m_max?.[i]==null)return '暂无气温';return `${f.temperature_2m_min[i]}—${f.temperature_2m_max[i]}°`;}
function renderWeather(){const r=selected;if(!r)return;const fi=r.forecast.time.indexOf(date),hi=r.history.time.indexOf(TripDates.previous(date));$('weather-values').innerHTML=`<div class="weather-card"><span class="label">${date.slice(0,4)} · 当日预报</span>${fi<0?`<strong class="weather-empty">${r.forecast_status==='pending'?'正在更新':r.forecast_status==='error'?'预报查询失败':'尚无可用预报'}</strong><span class="rain">${r.forecast_status==='error'?'保存出行日期可重试':'仅显示预报范围内的数据'}</span>`:`<strong class="temp">${range(r.forecast,fi)}</strong><span class="rain">降水概率 ${value(r.forecast.precipitation_probability_max,fi,'%')}</span>`}</div><div class="weather-card history"><span class="label">${TripDates.previous(date).slice(0,4)} · 同期历史参考</span><strong class="temp">${r.history_status==='pending'?'正在更新':r.history_status==='error'?'历史查询失败':range(r.history,hi)}</strong><span class="rain">降水量 ${value(r.history.precipitation_sum,hi,' mm')}</span></div>`;const note=document.querySelector('.weather-note');if(note)note.textContent=weatherNote(r);}
function renderDetail(){const r=selected;date=plannedDate(r)||(data.trip_dates.includes(date)?date:data.trip_dates[0]);const entrance=['P21','P22'].includes(r.id)?data.records.find(p=>p.id==='P20'):null;$('detail').innerHTML=`<div class="detail-header"><span class="detail-region">${esc(r.group)}</span><button class="close" id="close-detail" aria-label="关闭地点详情">×</button><h2>${esc(pretty(r))}</h2><div class="alt-badge">${Number.isFinite(r.elevation)?`海拔约 <strong>${r.elevation.toLocaleString()}</strong> 米`:'海拔暂无数据'}</div></div><div class="detail-body"><form id="day-form" class="day-editor"><label for="place-day">行程第几天</label><div class="day-controls"><input id="place-day" type="number" inputmode="numeric" min="1" max="99" step="1" placeholder="未安排" value="${placeDay(r)??''}" aria-describedby="day-message"><button type="submit">保存</button><button id="clear-day" type="button">清除</button></div><p id="day-message" role="status">${esc(dayMessage(r))}</p></form><p class="coordinates">${Number(r.lon).toFixed(4)}°E, ${Number(r.lat).toFixed(4)}°N</p><p class="access">${esc(r.access)}</p><p class="point-note">${esc(r.point||'')} ${longWalk.has(r.id)?'地图标记不代表车辆可直达；到达方式见上方。':''}</p><div class="weather-title"><span>出行天气</span><label for="date">选择游玩日期</label></div><select id="date" class="date-select">${!data.trip_dates.includes(date)?`<option value="${date}" selected>${date} · 超出行程范围</option>`:''}${data.trip_dates.map(d=>`<option value="${d}" ${d===date?'selected':''}>${d.replace('-','年').replace('-','月')}日 · ${['周日','周一','周二','周三','周四','周五','周六'][new Date(d+'T12:00:00+08:00').getUTCDay()]}</option>`).join('')}</select><div id="weather-values" class="weather-grid"></div><p class="weather-note">${esc(weatherNote(r))}</p><div class="detail-actions"><a class="primary" target="_blank" rel="noopener noreferrer" href="${link(entrance||r)}">${entrance?'高德查看游客中心':'高德查看位置'} ↗</a><a href="${esc(r.access_source||r.url)}" target="_blank" rel="noopener noreferrer">到达方式来源 ↗</a></div>${r.custom?`<div class="custom-actions"><button id="refresh-custom">重新查询海拔与天气</button><button id="remove-custom">移除此新增地点</button></div>`:''}<details><summary>数据来源与说明</summary><p>坐标：${esc(r.crs)}。${esc(r.coordinate_note||'')}。海拔按标记点地形数据估算并取整。降水概率取日内最高逐小时值；历史降水量并非历史降水概率。山区局部天气可能与格点数据不同。</p><div class="source-links"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">地点来源</a>${r.elevation_source?`<a href="${esc(r.elevation_source)}" target="_blank" rel="noopener noreferrer">海拔数据</a>`:''}${r.forecast_url?`<a href="${esc(r.forecast_url)}" target="_blank" rel="noopener noreferrer">预报数据</a>`:''}${r.history_url?`<a href="${esc(r.history_url)}" target="_blank" rel="noopener noreferrer">历史数据</a>`:''}<a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Weather data by Open-Meteo</a></div></details></div>`;initDayEditor(r);if(r.custom){$('remove-custom').onclick=()=>removeCustomPlace(r.id);$('refresh-custom').onclick=e=>{e.target.disabled=true;e.target.textContent='查询中…';enrichPlace(r);};}$('close-detail').onclick=closeDetail;$('date').onchange=e=>{date=e.target.value;renderWeather();saveState();};renderWeather();}
async function init(){if(!window.L)throw Error('地图组件未能加载，请刷新页面。');const res=await fetch('places.json');if(!res.ok)throw Error('地点数据暂时无法加载。');data=await res.json();customPlaces=loadCustomPlaces();data.records.push(...customPlaces);$('total').textContent=data.records.length;$('group-total').textContent=new Set(data.records.map(r=>r.group)).size;[...new Set(data.records.map(r=>r.group))].forEach((g,i)=>colors.set(g,palette[i%palette.length]));$('region').innerHTML+=[...colors.keys()].map(g=>`<option>${esc(g)}</option>`).join('');renderElevationLegend();map=await createTripMap('map');$('labels-toggle').onclick=()=>{showLabels=!showLabels;updateLabels();saveState();};$('place-list').onclick=e=>{const toggle=e.target.closest('[data-toggle]');if(toggle){togglePlace(toggle.dataset.toggle);return;}const el=e.target.closest('[data-id]');if(el)select(el.dataset.id);};['search','region','altitude','walking'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',filter));$('reset').onclick=()=>{$('search').value='';$('region').value='';$('altitude').value='';$('walking').checked=false;closeDetail();filter();};$('close-list').onclick=()=>{document.querySelector('.sidebar').classList.remove('open');$('list-toggle').setAttribute('aria-expanded','false');$('list-toggle').textContent='地点列表';};$('list-toggle').onclick=()=>{const open=document.querySelector('.sidebar').classList.toggle('open');$('list-toggle').setAttribute('aria-expanded',String(open));$('list-toggle').textContent=open?'关闭列表':'地点列表';if(open&&selected)locateInList(selected.id);};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDetail();document.querySelector('.sidebar').classList.remove('open');$('list-toggle').setAttribute('aria-expanded','false');$('list-toggle').textContent='地点列表';}});restoreTrip();const saved=readState();
if(Array.isArray(saved.hidden))saved.hidden.filter(id=>data.records.some(r=>r.id===id)).forEach(id=>hiddenPlaces.add(id));
showLabels=saved.showLabels===true;if(data.trip_dates.includes(saved.date))date=saved.date;
$('search').value=typeof saved.query==='string'?saved.query:'';
$('region').value=colors.has(saved.region)?saved.region:'';
$('altitude').value=['3500','4000','high'].includes(saved.altitude)?saved.altitude:'';
$('walking').checked=saved.walking===true;filter();
if(visible.some(r=>r.id===saved.selected))select(saved.selected);
if(Array.isArray(saved.center)&&saved.center.length===2&&saved.center.every(Number.isFinite)&&Math.abs(saved.center[0])<=85&&Math.abs(saved.center[1])<=180&&Number.isFinite(saved.zoom)&&saved.zoom>=0&&saved.zoom<=19)map.setView(saved.center,saved.zoom,{animate:false});
if(Number.isFinite(saved.listScroll))$('place-list').scrollTop=saved.listScroll;
ready=true;map.on('moveend zoomend',saveState);$('place-list').addEventListener('scroll',saveState,{passive:true});saveState();initPlaceSearch();initTripEditor();registerAgentTools();}
init().catch(e=>{$('fatal').hidden=false;$('fatal').textContent=e.message;console.error(e);});

function registerAgentTools(){
 const ctx=document.modelContext;if(!ctx?.registerTool)return;
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const defs=[{
 name:'list_trip_places',title:'查看旅行地点',description:'返回当前筛选出的川西地点及海拔，不改变页面。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({places:visible.map(r=>({id:r.id,name:pretty(r),elevation:r.elevation,group:r.group,shownOnMap:!hiddenPlaces.has(r.id)})),selected:selected?.id??null,date})
 },{
 name:'show_trip_place',title:'显示地点与天气',description:'按地点 ID 打开地图详情；可指定当前出行时间段内的日期。必要时清空筛选以显示该地点。',inputSchema:{type:'object',properties:{id:{type:'string'},date:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{
 if(!input||typeof input.id!=='string'||!data.records.some(r=>r.id===input.id))throw Error('未知地点 ID');
 if(input.date!==undefined&&!data.trip_dates.includes(input.date))throw Error('日期不在旅行期间');
 if(input.date)date=input.date;
 if(!visible.some(r=>r.id===input.id)){$('search').value='';$('region').value='';$('altitude').value='';$('walking').checked=false;filter();}
 select(input.id);return {id:selected.id,name:pretty(selected),date,forecastAvailable:selected.forecast.time.includes(date)};
 }}];
 for(const def of defs){try{Promise.resolve(ctx.registerTool(def,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}
